회의실 예약 현황판:
```html
<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <title>회의실 예약 현황판</title>
    <style>
        body { font-family: sans-serif; background: #f4f7f6; padding: 20px; color: #333; }
        .container { max-width: 800px; margin: 0 auto; background: #fff; padding: 20px; border-radius: 12px; box-shadow: 0 4px 6px rgba(0,0,0,0.1); }
        h1 { color: #2c3e50; border-bottom: 2px solid #eee; padding-bottom: 10px; }
        .room-card { border: 1px solid #ddd; border-radius: 8px; padding: 15px; margin-bottom: 10px; display: flex; justify-content: space-between; align-items: center; }
        .status-badge { padding: 5px 10px; border-radius: 20px; font-size: 0.8em; font-weight: bold; }
        .available { background: #d4edda; color: #155724; }
        .booked { background: #f8d7da; color: #721c24; }
        .controls { margin-top: 20px; padding: 15px; background: #f9f9f9; border-radius: 8px; }
        input, button { padding: 8px; margin: 5px; border: 1px solid #ccc; border-radius: 4px; }
        button { background: #3498db; color: white; border: none; cursor: pointer; }
        button:hover { background: #2980b9; }
        #msg { margin-top: 10px; font-size: 0.9em; color: #e74c3c; }
    </style>
</head>
<body>
    <div class="container">
        <h1>회의실 예약 시스템 📅</h1>
        <div id="room-list"></div>

        <div class="controls">
            <h3>회의실 예약하기</h3>
            <select id="roomSelect">
                <option value="대회의실">대회의실</option>
                <option value="중회의실">중회의실</option>
                <option value="소회의실">소회의실</option>
            </select>
            <input type="text" id="userName" placeholder="예약자 성함">
            <button onclick="bookRoom()">예약 완료</button>
            <div id="msg"></div>
        </div>
    </div>

    <script>
        let rooms = [
            { name: "대회의실", status: "예약 가능", user: "-" },
            { name: "중회의실", status: "예약 중", user: "김철수" },
            { name: "소회의실", status: "예약 가능", user: "-" }
        ];

        function render() {
            const list = document.getElementById('room-list');
            list.innerHTML = rooms.map(r => `
                <div class="room-card">
                    <div><strong>${r.name}</strong> (${r.user})</div>
                    <div class="status-badge ${r.status === '예약 가능' ? 'available' : 'booked'}">${r.status}</div>
                </div>
            `).join('');
        }

        function bookRoom() {
            const roomName = document.getElementById('roomSelect').value;
            const userName = document.getElementById('userName').value;
            const msg = document.getElementById('msg');

            if (!userName) {
                msg.textContent = "예약자 성함을 입력해주세요.";
                return;
            }

            const room = rooms.find(r => r.name === roomName);
            if (room.status === '예약 중') {
                msg.textContent = "이미 예약된 회의실입니다.";
            } else {
                room.status = '예약 중';
                room.user = userName;
                msg.textContent = roomName + " 예약이 완료되었습니다.";
                render();
            }
        }

        render();
    </script>
</body>
</html>
