민원 접수 폼:
```html
<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <title>공공 민원 접수 시스템</title>
    <style>
        body { font-family: sans-serif; background: #f4f7f6; display: flex; justify-content: center; padding: 20px; }
        .card { background: white; width: 100%; max-width: 500px; padding: 30px; border-radius: 12px; box-shadow: 0 4px 6px rgba(0,0,0,0.1); }
        h2 { color: #333; margin-top: 0; }
        .input-group { margin-bottom: 15px; }
        label { display: block; margin-bottom: 5px; font-weight: bold; }
        input, textarea, select { width: 100%; padding: 10px; border: 1px solid #ddd; border-radius: 6px; box-sizing: border-box; }
        button { background: #007bff; color: white; border: none; padding: 12px; width: 100%; border-radius: 6px; cursor: pointer; margin-top: 10px; }
        button:hover { background: #0056b3; }
        #message { margin-top: 15px; padding: 10px; border-radius: 6px; display: none; }
        .list-item { background: #f9f9f9; padding: 10px; margin-top: 10px; border-left: 4px solid #007bff; }
    </style>
</head>
<body>

<div class="card">
    <h2>민원 접수 센터</h2>
    <div class="input-group">
        <label>민원 유형</label>
        <select id="type">
            <option>도로 보수</option>
            <option>가로등 교체</option>
            <option>환경 정화</option>
        </select>
    </div>
    <div class="input-group">
        <label>민원 내용</label>
        <textarea id="content" rows="4" placeholder="상세 내용을 입력하세요"></textarea>
    </div>
    <button onclick="submitRequest()">접수하기</button>
    <div id="message"></div>
    <hr>
    <h3>최근 접수 내역</h3>
    <div id="requestList">
        <div class="list-item"><strong>도로 보수</strong>: 파손된 보도블록 보수 요청</div>
        <div class="list-item"><strong>가로등 교체</strong>: 3번 버스정류장 앞 가로등 불량</div>
    </div>
</div>

<script>
    function submitRequest() {
        const type = document.getElementById('type').value;
        const content = document.getElementById('content').value;
        const msg = document.getElementById('message');
        const list = document.getElementById('requestList');

        if (!content) {
            msg.innerText = "민원 내용을 입력해주세요.";
            msg.style.display = "block";
            msg.style.background = "#ffdada";
            return;
        }

        const div = document.createElement('div');
        div.className = 'list-item';
        div.innerHTML = `<strong>${type}</strong>: ${content}`;
        list.prepend(div);

        msg.innerText = "접수가 완료되었습니다.";
        msg.style.display = "block";
        msg.style.background = "#d4edda";
        document.getElementById('content').value = '';
    }
</script>
</body>
</html>
